BEGIN;
INSERT INTO users(id,email,password_hash,name,role) VALUES(91001,'workflow-admin@test.invalid','unused','Workflow Admin','admin'),(91002,'workflow-consultant@test.invalid','unused','Consultant','consultant'),(91003,'workflow-viewer@test.invalid','unused','Viewer','viewer');
INSERT INTO clients(id,client_number,full_name,case_officer_id) VALUES(91001,'TEST-CLIENT-1','Test Client',91002),(91002,'TEST-CLIENT-2','Other Client',91001);
INSERT INTO cases(id,client_id,service_category,destination) VALUES(91001,91001,'Test Visa','Test Country'),(91002,91002,'Other','Other');
DO $$
DECLARE v jsonb; n integer; tok text; doc integer; invoice integer; payment integer;
BEGIN
 PERFORM crm_command(91001,'template','{"service":"Test Visa","destination":"*","title":"Passport","category":"Passport"}');
 IF (SELECT count(*) FROM case_requirements WHERE case_id=91001)<>1 THEN RAISE EXCEPTION 'Template not applied'; END IF;
 BEGIN INSERT INTO cases(client_id,service_category,stage) VALUES(91001,'Test Visa','Submitted'); RAISE EXCEPTION 'Expected initial checklist rejection'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Expected initial checklist rejection' THEN RAISE; END IF; END;
 BEGIN UPDATE cases SET stage='Submitted' WHERE id=91001; RAISE EXCEPTION 'Expected blocker'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Expected blocker' THEN RAISE; END IF; END;
 INSERT INTO documents(client_id,filename,mime_type,content,category,review_status) VALUES(91001,'passport.pdf','application/pdf','\x255044462d','Passport','Approved') RETURNING id INTO doc;
 SELECT id INTO n FROM case_requirements WHERE case_id=91001;
 PERFORM crm_command(91002,'completeRequirement',jsonb_build_object('id',n,'completed',true,'document_id',doc));
 UPDATE cases SET stage='Submitted' WHERE id=91001;
 IF NOT EXISTS(SELECT 1 FROM case_history WHERE case_id=91001 AND details->'after'->>'stage'='Submitted') THEN RAISE EXCEPTION 'Missing case history'; END IF;
 UPDATE documents SET expires_on=current_date-1 WHERE id=doc;
 BEGIN UPDATE cases SET stage='Completed' WHERE id=91001; RAISE EXCEPTION 'Expected expiry blocker'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Expected expiry blocker' THEN RAISE; END IF; END;
 UPDATE documents SET expires_on=current_date+365 WHERE id=doc;
 BEGIN UPDATE documents SET review_status='Rejected',rejection_reason='' WHERE id=doc; RAISE EXCEPTION 'Expected rejection reason'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Expected rejection reason' THEN RAISE; END IF; END;
 INSERT INTO documents(client_id,filename,mime_type,content,category,replaces_id) VALUES(91001,'new-passport.pdf','application/pdf','\x255044462d','Passport',doc);
 IF EXISTS(SELECT 1 FROM case_requirements r WHERE case_id=91001 AND crm_requirement_ready(r)) THEN RAISE EXCEPTION 'Superseded evidence accepted'; END IF;
 -- Restore the original to continue the other independent workflow checks.
 DELETE FROM documents WHERE replaces_id=doc;
 PERFORM crm_command(91002,'task','{"case_id":91001,"title":"Prepare file","due_date":"2020-01-01"}');
 IF NOT EXISTS(SELECT 1 FROM tasks WHERE case_id=91001 AND client_id=91001) THEN RAISE EXCEPTION 'Case task not linked'; END IF;
 PERFORM crm_command(91002,'communication','{"client_id":91001,"kind":"Call","body":"Discussed requirements"}');
 v=crm_command(91002,'invoice','{"client_id":91001,"description":"Visa fee","currency":"PHP","amount_minor":10000,"due_date":"2027-01-01"}'); invoice=(v->>'id')::integer;
 PERFORM crm_command(91002,'installment',jsonb_build_object('invoice_id',invoice,'amount_minor',5000,'due_date','2027-01-01'));
 PERFORM crm_command(91002,'payment',jsonb_build_object('invoice_id',invoice,'amount_minor',4000,'reference','TEST-RECEIPT-1','received_on','2026-10-17'));
 BEGIN PERFORM crm_command(91002,'payment',jsonb_build_object('invoice_id',invoice,'amount_minor',7000,'reference','TEST-OVERPAY','received_on','2026-10-17')); RAISE EXCEPTION 'Expected overpayment rejection'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Expected overpayment rejection' THEN RAISE; END IF; END;
 v=crm_command(91002,'portalLink','{"client_id":91001}');tok=v->>'token';
 INSERT INTO communications(client_id,kind,body) VALUES(91001,'Message','Portal question');
 PERFORM crm_command(91002,'communication','{"client_id":91001,"kind":"Message","body":"Portal response","portal_visible":true}');
 v=crm_portal(tok);
 IF jsonb_array_length(v->'messages')<>2 OR v::text LIKE '%Discussed requirements%' THEN RAISE EXCEPTION 'Portal conversation privacy failed'; END IF;
 IF v->'client'->>'full_name'<>'Test Client' OR v::text LIKE '%password_hash%' THEN RAISE EXCEPTION 'Invalid portal data'; END IF;
 SELECT id INTO n FROM portal_access WHERE client_id=91001;
 PERFORM crm_command(91002,'revokePortal',jsonb_build_object('id',n));
 BEGIN PERFORM crm_portal(tok); RAISE EXCEPTION 'Expected revoked link rejection'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Expected revoked link rejection' THEN RAISE; END IF; END;
 UPDATE access_settings SET consultant_scope='assigned';
 IF crm_can_access(91002,'client',91002) OR NOT crm_can_access(91002,'client',91001) THEN RAISE EXCEPTION 'Ownership scope failed'; END IF;
 v=crm_snapshot(91002);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v->'clients') r WHERE (r->>'id')::integer=91002) THEN RAISE EXCEPTION 'Snapshot leaked record'; END IF;
 BEGIN PERFORM crm_command(91002,'requirement','{"case_id":91002,"title":"Unauthorized"}'); RAISE EXCEPTION 'Expected access rejection'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Expected access rejection' THEN RAISE; END IF; END;
 BEGIN PERFORM crm_command(91003,'task','{"client_id":91001,"title":"Unauthorized"}'); RAISE EXCEPTION 'Expected viewer rejection'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Expected viewer rejection' THEN RAISE; END IF; END;
 PERFORM crm_command(91001,'handoff','{"client_id":91001,"officer_id":91001}');
 IF NOT EXISTS(SELECT 1 FROM case_history WHERE case_id=91001 AND event='Handoff') THEN RAISE EXCEPTION 'Handoff history missing'; END IF;
 INSERT INTO leads(id,lead_number,full_name,email,phone,consultant_id,next_followup) VALUES(91001,'TEST-LEAD-1','Lead','duplicate@test.invalid','+63 999 123',91002,current_date-1);
 BEGIN INSERT INTO leads(lead_number,full_name,email) VALUES('TEST-DUP','Duplicate',' DUPLICATE@test.invalid '); RAISE EXCEPTION 'Expected duplicate rejection'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Expected duplicate rejection' THEN RAISE; END IF; END;
 INSERT INTO tasks(lead_id,title,status) VALUES(91001,'Survives conversion','Pending');
 UPDATE leads SET converted_client_id=91001,stage='Converted' WHERE id=91001;
 IF NOT EXISTS(SELECT 1 FROM tasks WHERE lead_id=91001 AND client_id=91001) THEN RAISE EXCEPTION 'Conversion lost task'; END IF;
 INSERT INTO leads(id,lead_number,full_name,consultant_id,next_followup) VALUES(91002,'TEST-LEAD-2','Followup',91002,current_date-1);
 PERFORM crm_generate_reminders(); SELECT count(*) INTO n FROM notifications; PERFORM crm_generate_reminders();
 IF n<>(SELECT count(*) FROM notifications) THEN RAISE EXCEPTION 'Reminder duplicate'; END IF;
 IF n=0 THEN RAISE EXCEPTION 'No reminders generated'; END IF;
 -- Credential changes revoke sessions, including administrator-assisted recovery.
 INSERT INTO auth_sessions(token_hash,user_id) VALUES(sha256('session-a'::bytea),91002);
 UPDATE users SET password_hash='changed' WHERE id=91002;
 IF EXISTS(SELECT 1 FROM auth_sessions WHERE user_id=91002 AND revoked_at IS NULL) THEN RAISE EXCEPTION 'Password reset did not revoke sessions'; END IF;
 INSERT INTO leads(id,lead_number,full_name) VALUES(91003,'TEST-MERGE-A','Merge Source'),(91004,'TEST-MERGE-B','Merge Destination');
 INSERT INTO tasks(lead_id,title) VALUES(91003,'Merge task');
 PERFORM crm_command(91001,'merge','{"kind":"lead","id":91003,"target_id":91004}');
 IF EXISTS(SELECT 1 FROM leads WHERE id=91003) OR NOT EXISTS(SELECT 1 FROM tasks WHERE lead_id=91004 AND title='Merge task') THEN RAISE EXCEPTION 'Lead merge lost work'; END IF;
 INSERT INTO clients(id,client_number,full_name) VALUES(91003,'TEST-MERGE-CLIENT','Merge Client');
 PERFORM crm_command(91001,'merge','{"kind":"client","id":91001,"target_id":91003}');
 IF NOT EXISTS(SELECT 1 FROM cases WHERE id=91001 AND client_id=91003) OR NOT EXISTS(SELECT 1 FROM invoices WHERE id=invoice AND client_id=91003) THEN RAISE EXCEPTION 'Client merge lost work'; END IF;
 IF crm_can_access(91001,'client',987654321) THEN RAISE EXCEPTION 'Nonexistent record permitted'; END IF;
 RAISE NOTICE 'PASS: workflows, blockers, documents, tasks, history, communication, billing, portal, permissions, duplicates and reminders';
END $$;
ROLLBACK;
